// exit 0 lab shell: manual pages. Short, original summaries of the options the Linux Essentials
// lessons use (not copies of the real pages). shell.js renders them for man, info, whatis, apropos and --help.
// Keys are the command name; a page in another section uses "name.section" (passwd.5).
(function (root, factory) {
  const pages = factory();
  if (typeof module === "object" && module.exports) module.exports = pages;
  else root.LEManPages = pages;
})(typeof self !== "undefined" ? self : this, function () {
  "use strict";
  const P = {};
  const page = (key, name, section, summary, rest) => { P[key] = Object.assign({ name, section, summary }, rest); };

  // ---------------------------------------------------------------- getting help
  page("man", "man", 1, "an interface to the system reference manuals", {
    synopsis: ["man [SECTION] PAGE...", "man -k KEYWORD", "man -f PAGE"],
    description: "man shows the manual page for a command, file format or concept. Pages are grouped into numbered sections; if no section is given, man searches them in order and shows the first match.\nSections: 1 user commands, 2 system calls, 3 library calls, 4 special files (/dev), 5 file formats (for example /etc/passwd), 6 games, 7 overviews and conventions, 8 system administration commands (usually need root), 9 kernel routines.",
    options: [["-k KEYWORD", "Search the short descriptions of all pages for KEYWORD. Same as apropos."], ["-f PAGE", "Show the one-line description of PAGE in every section. Same as whatis."]],
    examples: [["man 5 passwd", "The format of the /etc/passwd file, not the passwd command."], ["man -k partition", "Every page that mentions partitions in its description."], ["man gzip | grep -A1 -- -k", "Find one option without paging: pipe the page into grep."]],
    sections: [["KEYS IN THE PAGER", ["Space / PgDn   next page        b / PgUp   previous page", "/text          search forward   n          next match", "g / G          top / bottom     q          quit"]],
      ["READING A PAGE", ["NAME         what the command does, in one line", "SYNOPSIS     how to type it:", "               [ ]   optional         ...   may be repeated", "               a|b   one or the other  CAPS  replace with your own value", "OPTIONS      what each option changes", "EXAMPLES     typical commands to adapt (jump there with /EXAMPLES)", "SEE ALSO     related commands worth a look"]],
      ["FINDING HELP", ["Know the command?      man NAME, or NAME --help for a short summary", "Know only the task?    apropos WORD (man -k WORD), e.g. apropos compress", "Is it a builtin?       type NAME; builtins (cd, echo, if, for ...) use help NAME", "Pipes, redirection,    man bash: see PIPELINES, REDIRECTION, QUOTING,", "quoting, scripts       EXPANSION and COMPOUND COMMANDS", "Patterns               man 7 glob (wildcards), man 7 regex (grep and sed)"]]],
    see: ["apropos(1)", "whatis(1)", "info(1)", "help (bash builtin)"] });
  page("info", "info", 1, "read Info documents", {
    synopsis: ["info [PAGE]"],
    description: "info reads documentation in the Info format, which is organised as a tree of nodes linked by menus, like a small offline website. GNU projects such as coreutils and bash keep their most complete documentation in Info. If no Info document exists for a name, info shows the man page instead.",
    sections: [["KEYS", ["Tab      next link          Enter    follow link", "n / p    next / previous node   u    up one level", "l        go back            q        quit"]]],
    see: ["man(1)"], examples: [["info coreutils", "The full GNU coreutils manual: every basic file and text command."], ["info ls", "The ls node, or the man page if there is no Info node."]] });
  page("whatis", "whatis", 1, "display one-line manual page descriptions", { synopsis: ["whatis NAME..."], description: "whatis prints the NAME line of each matching manual page, in every section it exists in.", see: ["apropos(1)", "man(1)"], examples: [["whatis passwd", "Shows both passwd(1), the command, and passwd(5), the file format."], ["whatis ls cp mv", "One line for each command."]] });
  page("apropos", "apropos", 1, "search the manual page names and descriptions", { synopsis: ["apropos KEYWORD..."], description: "apropos searches the short descriptions of all installed manual pages for a keyword. Use it when you know what you want to do but not which command does it. It is the same as man -k.", see: ["whatis(1)", "man(1)"], examples: [["apropos compress", "Every page whose description mentions compressing."], ["apropos 'user account'", "Commands that work with user accounts."]] });
  page("locate", "locate", 1, "find files by name, quickly", {
    synopsis: ["locate [OPTION]... PATTERN..."],
    description: "locate searches a database of file names built by updatedb instead of walking the disk, so it is very fast. Because the database is only refreshed periodically (usually daily), files created since the last run are not found until updatedb runs again. A pattern without wildcards matches anywhere in the path; a pattern with * or ? must match the whole path.",
    options: [["-i, --ignore-case", "Ignore case when matching."], ["-l N, --limit N", "Stop after printing N matches."], ["-c, --count", "Print only the number of matches."], ["-e, --existing", "Print only files that still exist."], ["-b, --basename", "Match only the last part of each path."], ["-S, --statistics", "Show statistics about the database."]],
    see: ["updatedb(8)", "find(1)"], examples: [["locate -i readme", "Every path containing readme in any case."], ["locate -c '*.conf'", "How many paths end in .conf."], ["sudo updatedb; locate newfile", "Refresh the database first so a new file shows up."]] });
  page("updatedb", "updatedb", 8, "update the database used by locate", { synopsis: ["updatedb"], description: "updatedb scans the file system and rewrites the database that locate searches. It normally runs once a day from a timer or cron job. It needs root, so run it with sudo after creating files you want locate to find right away.", files: [["/var/lib/plocate/plocate.db", "The database."]], see: ["locate(1)"], examples: [["sudo updatedb", "Rebuild the database now."]] });
  page("find", "find", 1, "search for files in a directory hierarchy", {
    synopsis: ["find [PATH...] [EXPRESSION]"],
    description: "find walks the directory tree starting at each PATH (default: the current directory) and prints every file that matches all the tests in the expression. Unlike locate it looks at the disk itself, so results are always current, but it is slower.",
    options: [["-name PATTERN", "Base name matches the shell pattern. Quote it so the shell doesn't expand it: find . -name '*.txt'"], ["-iname PATTERN", "Like -name but ignores case."], ["-type f|d|l", "Regular file, directory or symbolic link."], ["-user NAME", "Owned by user NAME."], ["-perm MODE", "Permissions are exactly MODE (octal)."], ["-maxdepth N", "Descend at most N levels below the starting points."]],
    see: ["locate(1)"], examples: [["find /var/log -name '*.log'", "Every file under /var/log ending in .log."], ["find ~ -type d -name 'back*'", "Directories in your home whose name starts with back."], ["find /etc -maxdepth 1 -iname '*CONF*'", "Only directly in /etc, ignoring case."], ["find . -name '*.tmp' | wc -l", "Count the matches by piping into wc."]] });
  page("help", "help", 1, "display information about bash builtin commands", { synopsis: ["help [BUILTIN]"], description: "Builtins such as cd, export and type are part of bash itself, so they have no man page of their own. help lists them; their full description is in man bash.", examples: [["help cd", "Usage of the cd builtin."], ["help if", "Syntax of if ... then ... fi."], ["help", "List every builtin and keyword."]] });

  // ---------------------------------------------------------------- the shell
  page("bash", "bash", 1, "GNU Bourne-Again SHell", {
    synopsis: ["bash [OPTIONS] [FILE [ARGUMENTS]]", "bash -c COMMANDS"],
    description: "bash reads commands and runs them. Started with no file it is interactive; given a file it runs it as a script. A child bash gets only the exported (environment) variables of its parent, so plain shell variables don't reach it.",
    options: [["-c STRING", "Run the commands in STRING, then exit."], ["-l, --login", "Behave as a login shell (read /etc/profile and ~/.profile)."]],
    sections: [["SPECIAL PARAMETERS", ["$0  name of the script      $1..$9  positional arguments", "$#  number of arguments      $@      all arguments, each separately", "$?  exit status of the last command (0 means success)", "$$  process ID of this shell"]],
      ["PIPELINES", ["cmd1 | cmd2          the output of cmd1 becomes the input of cmd2", "ls /etc | wc -l      count entries", "zcat x.gz | head     read a compressed file without unpacking it", "ps aux | grep ssh    filter a long listing", "Most text commands (head, tail, grep, sort, wc, cut ...) read the pipe when", "you give them no file name."]],
      ["REDIRECTION", ["> FILE      write output to FILE (replaces it)      >> FILE   append", "< FILE      read input from FILE", "2> FILE     write errors to FILE                    2>/dev/null  discard errors", "2>&1        send errors where output goes           &> FILE   both into FILE", "<<WORD      here document: the lines up to WORD become the input"]],
      ["QUOTING", ["'text'      exactly as typed: no $variables, no wildcards", "\"text\"      one word, but $VAR and $(command) are expanded", "\\x          a backslash makes the next character literal", "Quote names with spaces and patterns meant for the command (find -name '*.txt')."]],
      ["EXPANSION", ["~           your home directory          $VAR, ${VAR}   a variable's value", "$(cmd)      the output of cmd            $((2 + 3))     arithmetic", "{a,b}       a b                          {1..3}         1 2 3", "* ? [abc]   file name wildcards, see glob(7)"]],
      ["COMPOUND COMMANDS", ["cmd1 && cmd2           run cmd2 only if cmd1 succeeded", "cmd1 || cmd2           run cmd2 only if cmd1 failed", "cmd1 ; cmd2            one after the other", "if TEST; then ...; elif TEST; then ...; else ...; fi", "for NAME in WORDS; do ...; done", "while TEST; do ...; done        until TEST; do ...; done", "TEST is any command; [ ... ] is the test command, see test(1).", "help if, help for and help while show the details."]],
      ["EXIT STATUS", "Every command returns a number: 0 means success, anything else is a failure (grep returns 1 when nothing matched, 127 means command not found). echo $? shows the last one."],
      ["BUILTINS", "alias, cd, echo, exec, exit, export, help, history, kill, printf, pwd, read, set, shift, source, test, type, unalias, unset. Use help NAME for each; man NAME has no page for most of them."]],
    files: [["~/.bashrc", "Read by interactive non-login shells."], ["~/.profile", "Read by login shells."], ["~/.bash_history", "Saved command history."]],
    see: ["sh(1)", "env(1)", "test(1)", "glob(7)", "regex(7)", "help"], examples: [["bash myscript.sh", "Run a script even if it isn't executable."], ["bash -c 'echo $0'", "Run one command in a new shell."], ["ls /etc | grep conf > list.txt", "A pipeline whose result is redirected into a file (see PIPELINES and REDIRECTION)."]] });
  page("sh", "sh", 1, "command interpreter (shell)", { synopsis: ["sh [FILE]"], description: "On Debian and Ubuntu /bin/sh is dash, a small POSIX shell that runs scripts quickly; on Fedora and RHEL it is bash. Scripts that use bash-only features should start with #!/bin/bash.", see: ["bash(1)"], examples: [["sh myscript.sh", "Run a script with sh."]] });
  page("test", "test", 1, "check file types and compare values", {
    synopsis: ["test EXPRESSION", "[ EXPRESSION ]"],
    description: "test (also written [ ... ], with spaces inside the brackets) evaluates a condition and sets the exit status: 0 if true, 1 if false. It prints nothing, so it is used with if, while, && and ||. In bash it is a builtin; help test shows the same list.",
    options: [["-e FILE", "FILE exists."], ["-f FILE", "FILE exists and is a regular file."], ["-d FILE", "FILE exists and is a directory."], ["-r / -w / -x FILE", "You may read / write / execute FILE."], ["-s FILE", "FILE exists and isn't empty."], ["-z STRING / -n STRING", "STRING is empty / not empty."], ["S1 = S2, S1 != S2", "Strings are equal / different."], ["N1 -eq N2", "Numbers are equal; also -ne, -lt, -le, -gt, -ge."], ["! EXPR", "EXPR is false."]],
    examples: [["[ -d /etc ] && echo yes", "Prints yes because /etc is a directory."], ["if [ $# -lt 1 ]; then echo 'give a name'; exit 1; fi", "A script that needs one argument."], ["test -f notes.txt; echo $?", "0 if the file exists, 1 if not."]],
    see: ["bash(1)", "help test"] });
  page("glob", "glob", 7, "file name wildcards", { synopsis: ["* ? [...]"],
    description: "Before running a command, the shell replaces words containing wildcards with the matching file names, sorted. If nothing matches, the word is left as it is. Wildcards don't match a leading dot (hidden files) unless the pattern starts with one. Quote a pattern ('*.txt') to pass it to a command such as find instead of letting the shell expand it.",
    sections: [["PATTERNS", ["*        any characters, including none     *.txt   every .txt file", "?        exactly one character               file?.txt", "[abc]    one of a, b, c                      [0-9]   one digit", "[!abc]   one character that isn't a, b or c  [^0-9] means the same"]]],
    examples: [["ls *.conf", "Every name ending in .conf."], ["ls log?.txt", "log1.txt and logA.txt, not log10.txt."], ["ls report[0-9][0-9].pdf", "report00.pdf to report99.pdf."], ["echo .*", "Hidden names."]], see: ["bash(1)", "regex(7)", "find(1)"] });
  page("regex", "regex", 7, "regular expressions", { synopsis: ["grep PATTERN", "grep -E PATTERN", "sed 's/PATTERN/NEW/'"],
    description: "A regular expression describes text to match; grep, sed and many other tools use them. They are not the same as shell wildcards: here * means \"the previous item, any number of times\", not \"anything\". Basic expressions (grep, sed) need a backslash before ? + { } | ( ); extended ones (grep -E, egrep, sed -E) don't. Put patterns in single quotes so the shell leaves them alone.",
    sections: [["SYNTAX", [".        any one character            \\.       a literal dot", "^        start of the line            $        end of the line", "[abc]    one of a, b, c               [^abc]   any other character", "[0-9]    a digit                      [a-z]    a lowercase letter", "x*       x zero or more times         .*       anything", "x+       x one or more (-E)           x?       x optional (-E)", "x{3}     exactly 3 x (-E)             a|b      a or b (-E)", "(ab)+    group (-E)"]]],
    examples: [["grep '^#' /etc/fstab", "Comment lines."], ["grep -v '^$' notes.txt", "Drop empty lines."], ["grep -E '^[0-9]+$' list", "Lines that are only digits."], ["grep -E 'colou?r' words", "color or colour."]], see: ["grep(1)", "sed(1)", "glob(7)"] });
  page("echo", "echo", 1, "display a line of text", { synopsis: ["echo [-neE] [STRING]..."], description: "echo writes its arguments separated by spaces and followed by a newline. Bash has a builtin echo that runs instead of /usr/bin/echo.", options: [["-n", "Don't print the trailing newline."], ["-e", "Interpret backslash escapes such as \\n (newline) and \\t (tab)."], ["-E", "Don't interpret backslash escapes (default)."]], see: ["printf(1)"], examples: [["echo \"Hello, $USER\"", "Double quotes expand variables."], ["echo -n 'no newline'", "Leave the cursor on the same line."], ["echo -e 'a\\tb'", "Turn \\t into a tab."]] });
  page("printf", "printf", 1, "format and print data", { synopsis: ["printf FORMAT [ARGUMENT]..."], description: "printf prints its arguments under control of FORMAT, like the C function. Unlike echo it adds no newline unless the format contains \\n. Conversions: %s string, %d integer, %f decimal, %x hex; a width such as %5s pads, and %-5s pads on the right.", see: ["echo(1)"], examples: [["printf '%s is %d\\n' age 30", "Fill %s and %d in order; printf adds no newline unless you write \\n."], ["printf '%s\\n' one two three", "The format repeats for extra arguments."]] });
  page("env", "env", 1, "run a program in a modified environment, or print the environment", { synopsis: ["env [NAME=VALUE]... [COMMAND [ARG]...]"], description: "With no command, env prints every environment (exported) variable, one NAME=value per line. Shell variables that haven't been exported are not shown; use set to see those too.", options: [["-i", "Start with an empty environment."], ["-u NAME", "Remove NAME from the environment."]], see: ["printenv(1)", "export (bash builtin)"], examples: [["env | sort", "Every environment variable, sorted."], ["env | grep -c =", "How many variables are set."]] });
  page("printenv", "printenv", 1, "print all or part of the environment", { synopsis: ["printenv [VARIABLE]..."], description: "printenv prints the values of the named environment variables, or all of them. It only sees exported variables.", see: ["env(1)"], examples: [["printenv HOME", "The value of HOME."], ["printenv | grep PATH", "Every variable whose line mentions PATH."]] });
  page("which", "which", 1, "locate a command", { synopsis: ["which [-a] NAME..."], description: "which searches the directories in $PATH, in order, and prints the full path of the first executable file with each name. It doesn't know about aliases or shell builtins; use type for those.", options: [["-a", "Print every match, not just the first."]], see: ["type (bash builtin)", "whereis(1)"], examples: [["which ls", "The path of the program that runs for ls."], ["which -a bash", "Every match on PATH, not just the first."]] });
  page("date", "date", 1, "print or set the system date and time", {
    synopsis: ["date [OPTION]... [+FORMAT]"],
    description: "date prints the current date and time in the time zone named by the TZ variable (or the system zone). A +FORMAT argument chooses the fields: %Y year, %m month, %d day, %H:%M:%S time, %F the same as %Y-%m-%d, %T the same as %H:%M:%S, %A weekday name, %Z time zone abbreviation, %s seconds since 1970.",
    options: [["-u, --utc", "Print Coordinated Universal Time (UTC)."], ["-R", "Print in RFC 5322 format, as used in email."], ["-I", "Print in ISO 8601 format (YYYY-MM-DD)."]],
    examples: [["TZ=America/New_York date", "The time in New York, for this command only."], ["today=$(date +%F)", "Save today's date in a variable."]] });
  page("history", "history", 1, "the bash command history", { synopsis: ["history [N]"], description: "history lists previous commands with numbers. !! reruns the last command, !N reruns number N, !-N runs the command N back, and !text reruns the newest command starting with text. Bash saves the history to ~/.bash_history when it exits.", examples: [["history 5", "The last five commands."], ["history | grep tar", "Earlier commands that used tar."], ["!!", "Run the previous command again (!N runs number N)."]] });

  // ---------------------------------------------------------------- files and directories
  page("ls", "ls", 1, "list directory contents", {
    synopsis: ["ls [OPTION]... [FILE]..."],
    description: "ls lists the files in each directory given (default: the current directory), sorted by name. Names starting with a dot are hidden unless -a or -A is used. In long format (-l) each line shows the type and permissions, number of links, owner, group, size in bytes, modification time and name.",
    options: [["-a, --all", "Show all entries, including hidden ones and the . and .. directory links."], ["-A, --almost-all", "Show hidden entries but not . and .."], ["-l", "Long listing format."], ["-h, --human-readable", "With -l, show sizes like 1.5K, 23M, 2G."], ["-d, --directory", "List directories themselves, not their contents. ls -ld /tmp shows the permissions of /tmp."], ["-R, --recursive", "List subdirectories recursively."], ["-t", "Sort by modification time, newest first."], ["-S", "Sort by file size, largest first."], ["-X", "Sort alphabetically by extension."], ["-r, --reverse", "Reverse the sort order. ls -lrt puts the newest file last."], ["-i, --inode", "Print each file's inode number. Hard links share an inode."], ["-F, --classify", "Append / to directories, * to executables and @ to symbolic links."], ["-1", "One name per line."], ["--format=long", "Same as -l."]],
    examples: [["ls -lh /var/log", "Long listing with readable sizes."], ["ls -d */", "Only the directories in the current directory."], ["ls -lrS", "Long listing, smallest file first."]],
    see: ["tree(1)", "stat(1)", "du(1)"],
    info: "File: coreutils.info,  Node: ls invocation,  Next: dir invocation,  Up: Directory listing\n\n10.1 'ls': List directory contents\n==================================\n\nThe 'ls' program lists information about files (of any type, including\ndirectories).  Options and file arguments can be intermixed arbitrarily,\nas usual.  Later options override earlier options that are incompatible.\n\n* Menu:\n\n* Which files are listed::\n* What information is listed::\n* Sorting the output::\n* General output formatting::\n* Formatting file timestamps::\n* Formatting the file names::\n\n10.1.1 Which files are listed\n-----------------------------\n'-a' '--all'          List all files, including those starting with '.'.\n'-A' '--almost-all'   Like -a, but leave out '.' and '..'.\n'-d' '--directory'    List directories like other files, not their contents.\n'-R' '--recursive'    List the contents of all directories recursively.\n\n10.1.2 What information is listed\n---------------------------------\n'-l' '--format=long'  Long format: type, permissions, links, owner, group,\n                      size, timestamp and name.\n'-i' '--inode'        Print the inode number of each file.\n'-h' '--human-readable'  Print sizes like 1K 234M 2G.\n\n10.1.3 Sorting the output\n-------------------------\n'-r' '--reverse'      Reverse whatever the sorting method is.\n'-S' '--sort=size'    Sort by file size, largest first.\n'-t' '--sort=time'    Sort by modification time (the 'mtime'), newest first.\n'-X' '--sort=extension'  Sort alphabetically by file extension.\n'-U' '--sort=none'    Do not sort; list in directory order.\n\n10.1.4 General output formatting\n--------------------------------\n'-1'                  List one file per line.\n'-F' '--classify'     Append a character to each name showing its type." });
  page("pwd", "pwd", 1, "print name of current/working directory", { synopsis: ["pwd"], description: "pwd prints the absolute path of the current directory. Bash also keeps it in $PWD, and the previous directory in $OLDPWD (used by cd -).", examples: [["pwd", "Print where you are, for example /home/student."]] });
  page("tree", "tree", 1, "list contents of directories in a tree-like format", {
    synopsis: ["tree [OPTION]... [DIRECTORY]..."],
    description: "tree draws the directory hierarchy with indentation lines and ends with a count of directories and files. It is not installed by default on most distributions (package: tree).",
    options: [["-a", "Include hidden files."], ["-d", "List directories only."], ["-L LEVEL", "Descend at most LEVEL directories deep."], ["-F", "Append / to directories, * to executables, @ to links, like ls -F."], ["-f", "Print the full path of each entry."]], see: ["ls(1)"], examples: [["tree -L 2 /etc", "Only two levels deep."], ["tree -d ~", "Directories only."], ["tree -a project", "Include hidden files."]] });
  page("du", "du", 1, "estimate file space usage", {
    synopsis: ["du [OPTION]... [FILE]..."],
    description: "du reports how much disk space each directory uses, including everything below it, in 1 KiB blocks. Disk space is allocated in blocks (often 4 KiB), so a 5-byte file still uses a whole block. ls -l shows a directory's own size (usually 4096), not its contents; du shows the contents.",
    options: [["-h, --human-readable", "Print sizes like 4.0K, 12M."], ["-s, --summarize", "Print only a total for each argument."], ["-a, --all", "List files too, not just directories."], ["-c, --total", "Print a grand total at the end."], ["-d N, --max-depth=N", "Only list directories N or fewer levels below the argument."]],
    examples: [["du -sh ~", "How much space your home directory uses."]], see: ["df(1)", "ls(1)"] });
  page("mkdir", "mkdir", 1, "make directories", { synopsis: ["mkdir [OPTION]... DIRECTORY..."], description: "mkdir creates each directory. It fails if the directory exists or if its parent doesn't, unless -p is used.", options: [["-p, --parents", "Create missing parent directories too, and don't complain if a directory already exists."], ["-v, --verbose", "Print a message for each created directory."], ["-m MODE", "Set the permissions of the new directory, like chmod."]], see: ["rmdir(1)"], examples: [["mkdir -p projects/web/css", "Create the whole path, parents included."], ["mkdir -m 700 private", "Create it with permissions rwx------."]] });
  page("rmdir", "rmdir", 1, "remove empty directories", { synopsis: ["rmdir [OPTION]... DIRECTORY..."], description: "rmdir removes directories only if they are empty, which makes it a safe way to clean up. To delete a directory and everything in it, use rm -r.", options: [["-p, --parents", "Remove the directory and then each parent in the path, as long as they become empty: rmdir -p a/b/c removes c, then b, then a."], ["-v, --verbose", "Print a message for each directory removed."]], see: ["rm(1)", "mkdir(1)"], examples: [["rmdir emptydir", "Fails unless the directory is empty."], ["rmdir -p a/b/c", "Remove c, then b, then a, as long as each becomes empty."]] });
  page("touch", "touch", 1, "change file timestamps", { synopsis: ["touch [OPTION]... FILE..."], description: "touch sets each file's modification time to now. A file that doesn't exist is created empty, which is the most common use.", options: [["-a", "Change only the access time."], ["-m", "Change only the modification time."]], examples: [["touch notes.txt", "Create an empty file, or update its time if it exists."], ["touch a.txt b.txt c.txt", "Several at once."]] });
  page("cp", "cp", 1, "copy files and directories", {
    synopsis: ["cp [OPTION]... SOURCE DEST", "cp [OPTION]... SOURCE... DIRECTORY"],
    description: "cp copies SOURCE to DEST, or several sources into an existing DIRECTORY. An existing destination file is overwritten without asking. The copy belongs to you and gets a new timestamp unless -p or -a is used.",
    options: [["-r, -R, --recursive", "Copy directories and everything in them."], ["-i, --interactive", "Ask before overwriting."], ["-n, --no-clobber", "Never overwrite an existing file."], ["-u, --update", "Copy only when the source is newer than the destination, or the destination is missing."], ["-p", "Preserve mode, ownership and timestamps."], ["-a, --archive", "Like -rp: recursive and preserve everything. Good for backups."], ["-v, --verbose", "Print each file as it is copied."]],
    see: ["mv(1)", "rsync(1)"], examples: [["cp report.txt report.bak", "Copy a file under a new name."], ["cp -r photos /tmp/", "Copy a directory and everything in it."], ["cp -i *.txt backup/", "Ask before overwriting anything in backup/."]] });
  page("mv", "mv", 1, "move (rename) files", { synopsis: ["mv [OPTION]... SOURCE DEST", "mv [OPTION]... SOURCE... DIRECTORY"], description: "mv renames SOURCE to DEST, or moves sources into DIRECTORY. On the same file system it only changes the directory entry, so even huge files move instantly. An existing destination is overwritten without asking.", options: [["-i, --interactive", "Ask before overwriting."], ["-n, --no-clobber", "Never overwrite an existing file."], ["-u, --update", "Move only when the source is newer than the destination."], ["-v, --verbose", "Explain what is being done."], ["-f, --force", "Don't ask before overwriting (the default)."]], see: ["cp(1)", "rename(1)"], examples: [["mv draft.txt final.txt", "Rename a file."], ["mv *.jpg pictures/", "Move every .jpg into pictures/."], ["mv -i a.txt b.txt", "Ask if b.txt already exists."]] });
  page("rm", "rm", 1, "remove files or directories", { synopsis: ["rm [OPTION]... FILE..."], description: "rm deletes files. There is no trash can on the command line: removed files are gone. Directories need -r. rm refuses to remove . or .., and refuses / unless forced.", options: [["-r, -R, --recursive", "Remove directories and their contents."], ["-i", "Ask before every removal."], ["-f, --force", "Never ask, and ignore files that don't exist."], ["-v, --verbose", "Print each file as it is removed."], ["-d, --dir", "Remove empty directories."]], examples: [["rm -ri old/", "Remove old/ one entry at a time, answering y or n for each."]], see: ["rmdir(1)", "shred(1)"] });
  page("ln", "ln", 1, "make links between files", {
    synopsis: ["ln [OPTION]... TARGET LINK_NAME", "ln [OPTION]... TARGET DIRECTORY"],
    description: "ln creates a hard link by default: a second name for the same inode. Both names are equal; the data stays until the last name is removed. Hard links can't point to directories or cross file systems. ln -s creates a symbolic (soft) link instead: a small file that stores a path. It can point anywhere, but it breaks if the target is moved or deleted. A relative target is resolved from the link's own directory.",
    options: [["-s, --symbolic", "Make a symbolic link."], ["-f, --force", "Replace an existing destination."], ["-v, --verbose", "Print the name of each link."]], see: ["ls(1) (ls -li shows inode numbers)", "readlink(1)"], examples: [["ln -s /etc/hosts myhosts", "A symbolic link named myhosts pointing at /etc/hosts."], ["ln data.txt data-link.txt", "A hard link: a second name for the same inode."], ["ls -li", "Compare inode numbers to see which names are hard links."]] });
  page("readlink", "readlink", 1, "print resolved symbolic links", { synopsis: ["readlink FILE"], description: "readlink prints the path stored in a symbolic link.", examples: [["readlink /usr/bin/vi", "Where a symbolic link points."]] });
  page("file", "file", 1, "determine file type", { synopsis: ["file FILE..."], description: "file looks at a file's contents, not its name, to tell what it is: text, a script, a compressed archive, a program, a directory and so on. Linux doesn't rely on extensions.", examples: [["file /etc/hosts", "Reports ASCII text."], ["file *", "The type of everything in the current directory."]] });
  page("stat", "stat", 1, "display file status", { synopsis: ["stat [-c FORMAT] FILE..."], description: "stat shows everything the inode records about a file: size, inode number, link count, permissions in octal and symbolic form, owner and group.", options: [["-c FORMAT", "Print only the given fields: %a octal mode, %A symbolic mode, %U owner, %G group, %s size, %i inode, %h link count, %n name."]], examples: [["stat /etc/passwd", "Size, inode, links, permissions and times."], ["stat -c '%a %U' notes.txt", "Only the octal mode and owner."]] });

  // ---------------------------------------------------------------- reading files and text tools
  page("cat", "cat", 1, "concatenate files and print on the standard output", { synopsis: ["cat [OPTION]... [FILE]..."], description: "cat prints each file in order. With no file, or with -, it reads standard input. It's also used to join files: cat a b > both.", options: [["-n, --number", "Number every output line."], ["-A", "Show tabs as ^I and line ends as $."]], see: ["less(1)", "tac(1)"], examples: [["cat /etc/hostname", "Print a short file."], ["cat -n script.sh", "Print it with line numbers."], ["cat part1 part2 > whole", "Join two files into a new one."]] });
  page("less", "less", 1, "view a file one screen at a time", { synopsis: ["less [FILE]..."], description: "less is a pager: it shows a long file a screen at a time and lets you scroll both ways. man uses it to display pages.", sections: [["KEYS", ["Space / f   next page     b      previous page", "/pattern    search        n / N  next / previous match", "g / G       start / end   q      quit"]]], see: ["more(1)"], examples: [["less /var/log/syslog", "Scroll through a long file; q quits."], ["ps aux | less", "Page through the output of a command."]] });
  page("more", "more", 1, "file perusal filter for crt viewing", { synopsis: ["more [FILE]..."], description: "more is an older, simpler pager than less: it mainly scrolls forward. Space shows the next page and q quits.", see: ["less(1)"], examples: [["more /etc/services", "Page forward with Space."]] });
  page("head", "head", 1, "output the first part of files", { synopsis: ["head [OPTION]... [FILE]..."], description: "head prints the first 10 lines of each file, or of standard input.", options: [["-n N, -N", "Print the first N lines instead."], ["-c N", "Print the first N bytes."]], see: ["tail(1)"], examples: [["head /etc/passwd", "The first 10 lines."], ["head -n 5 notes.txt", "Only the first 5 lines."], ["ls -l /etc | head -n 4", "head also reads a pipe: the first lines of another command's output."]] });
  page("tail", "tail", 1, "output the last part of files", { synopsis: ["tail [OPTION]... [FILE]..."], description: "tail prints the last 10 lines of each file. It is the usual way to look at the newest entries in a log.", options: [["-n N, -N", "Print the last N lines instead."], ["-n +N", "Print from line N to the end."], ["-f, --follow", "Keep the file open and print new lines as they are written. Press Ctrl+C to stop."]], see: ["head(1)", "journalctl(1)"], examples: [["tail -n 20 /var/log/syslog", "The newest 20 lines of a log."], ["tail -n +2 data.csv", "Everything from line 2 on, which skips a header."], ["head -n 8 file | tail -n 1", "Line 8 alone."]] });
  page("wc", "wc", 1, "print newline, word, and byte counts for each file", { synopsis: ["wc [OPTION]... [FILE]..."], description: "wc prints the number of lines, words and bytes in each file, followed by the file name. Read the file from standard input (wc -l < file) to get the number without the name.", options: [["-l, --lines", "Count lines."], ["-w, --words", "Count words."], ["-c, --bytes", "Count bytes."], ["-m, --chars", "Count characters."]], examples: [["wc -l /etc/passwd", "How many lines, which here is how many accounts."], ["ls | wc -l", "How many entries are in this directory."], ["wc -w essay.txt", "Count words."]] });
  page("sort", "sort", 1, "sort lines of text files", { synopsis: ["sort [OPTION]... [FILE]..."], description: "sort prints the lines of its input in order. By default it compares whole lines as text, so 10 comes before 9; use -n for numbers.", options: [["-n, --numeric-sort", "Compare as numbers."], ["-r, --reverse", "Reverse the order."], ["-f, --ignore-case", "Fold lower case to upper case when comparing."], ["-u, --unique", "Print only the first of equal lines."], ["-k N", "Sort on field N (fields are separated by blanks unless -t is given)."], ["-t SEP", "Use SEP as the field separator, for example -t:"]], see: ["uniq(1)"], examples: [["sort names.txt", "Alphabetical order."], ["sort -n sizes.txt", "Numeric order, so 9 comes before 10."], ["sort -t: -k3 -n /etc/passwd", "Sort by the third colon-separated field (the UID) as numbers."]] });
  page("uniq", "uniq", 1, "report or omit repeated lines", { synopsis: ["uniq [OPTION]... [FILE]"], description: "uniq collapses adjacent identical lines into one. Lines must be next to each other, so it usually follows sort.", options: [["-c, --count", "Prefix lines with the number of times they occurred."], ["-d", "Print only repeated lines."], ["-u", "Print only lines that are not repeated."]], see: ["sort(1)"], examples: [["sort list.txt | uniq", "Remove duplicate lines (sort first so duplicates sit together)."], ["sort list.txt | uniq -c", "Count how often each line appears."], ["sort list.txt | uniq -d", "Only the lines that appear more than once."]] });
  page("cut", "cut", 1, "remove sections from each line of files", { synopsis: ["cut OPTION... [FILE]..."], description: "cut prints selected parts of each line: fields separated by a delimiter (TAB by default) or character positions.", options: [["-d DELIM", "Use DELIM instead of TAB to separate fields."], ["-f LIST", "Print these fields: 1, 1,3 or 2-4."], ["-c LIST", "Print these character positions."]], examples: [["cut -d: -f1,7 /etc/passwd", "User names and their login shells."]] });
  page("tr", "tr", 1, "translate or delete characters", { synopsis: ["tr [OPTION]... SET1 [SET2]"], description: "tr reads standard input (it doesn't take file names, so use < file) and replaces characters from SET1 with the matching ones in SET2. Ranges like a-z and classes like [:upper:] are allowed.", options: [["-d, --delete", "Delete characters in SET1."], ["-s, --squeeze-repeats", "Replace each run of a repeated character from the last set with a single one; tr -s ' ' turns many spaces into one."], ["-c", "Use the complement of SET1."]], examples: [["tr a-z A-Z < notes.txt", "Print notes.txt in upper case."], ["ls -l | tr -s ' ' | cut -d' ' -f9", "Squeeze spaces so cut can pick the ninth field."]] });
  page("grep", "grep", 1, "print lines that match patterns", {
    synopsis: ["grep [OPTION]... PATTERN [FILE]..."],
    description: "grep prints every line that contains a match for PATTERN, a regular expression. In basic regular expressions . matches any character, * repeats the previous item zero or more times, ^ and $ anchor to the start and end of the line, and [abc] matches one of a set. With -E (extended) +, ?, | and () work without backslashes.",
    options: [["-i, --ignore-case", "Ignore case."], ["-v, --invert-match", "Print lines that do NOT match."], ["-c, --count", "Print only the number of matching lines."], ["-n, --line-number", "Prefix each line with its line number."], ["-r, --recursive", "Search every file under each directory."], ["-l", "Print only the names of files that contain a match."], ["-w", "Match whole words only."], ["-o", "Print only the matching part of each line."], ["-q, --quiet", "Print nothing; only the exit status says whether a line matched (0 yes, 1 no). Handy in if and &&."], ["-E", "Use extended regular expressions (same as egrep)."], ["-F", "Treat PATTERN as a fixed string, not a regex."], ["-A N, -B N, -C N", "Also print N lines after, before, or around each match."]],
    examples: [["grep -i error /var/log/syslog", "Lines mentioning error in any case."], ["grep -E '^(root|daemon):' /etc/passwd", "Lines that start with root: or daemon:."], ["grep -c '^$' file", "Count empty lines."]], see: ["sed(1)", "regex(7)"] });
  page("egrep", "egrep", 1, "print lines that match extended patterns", { synopsis: ["egrep PATTERN [FILE]..."], description: "egrep is the same as grep -E. It is kept for compatibility; new scripts should use grep -E.", see: ["grep(1)"], examples: [["egrep 'cat|dog' pets.txt", "Lines with cat or dog; same as grep -E."]] });
  page("sed", "sed", 1, "stream editor for filtering and transforming text", { synopsis: ["sed [OPTION]... SCRIPT [FILE]..."], description: "sed reads its input line by line, applies editing commands and prints the result. The most common command is s/old/new/, which replaces the first match on each line; add g to replace every match. Commands can be limited to line numbers: 2d deletes line 2, 1,3p prints lines 1 to 3.", options: [["-n", "Don't print lines automatically; only lines selected with p are printed."], ["-i", "Edit the files in place instead of printing."], ["-E", "Use extended regular expressions."]], examples: [["sed 's/http:/https:/g' links.txt", "Print links.txt with every http: changed."], ["sed -n '5,10p' file", "Print only lines 5 to 10."]], see: ["grep(1)", "tr(1)"] });
  page("tee", "tee", 1, "read from standard input and write to standard output and files", { synopsis: ["tee [-a] FILE..."], description: "tee copies its input both to the screen and to files. Because it opens the files itself, sudo tee can write to a file you can't write to, which sudo with > can't do.", options: [["-a, --append", "Append to the files instead of overwriting them."]], examples: [["echo '10.0.0.5 nas' | sudo tee -a /etc/hosts", "Add a line to a root-owned file."]] });
  page("seq", "seq", 1, "print a sequence of numbers", { synopsis: ["seq [FIRST [STEP]] LAST"], description: "seq prints numbers from FIRST (default 1) to LAST, one per line.", examples: [["seq 5", "1 to 5, one per line."], ["seq 0 10 50", "0, 10, 20 ... 50."], ["for i in $(seq 3); do echo $i; done", "Loop over a range."]] });
  page("basename", "basename", 1, "strip directory and suffix from filenames", { synopsis: ["basename NAME [SUFFIX]"], description: "basename prints NAME with everything up to the last / removed, and SUFFIX removed if given: basename /etc/hosts.conf .conf prints hosts.", see: ["dirname(1)"], examples: [["basename /var/log/syslog", "Prints syslog."], ["basename /home/student/report.txt .txt", "Prints report."]] });
  page("dirname", "dirname", 1, "strip last component from file name", { synopsis: ["dirname NAME..."], description: "dirname prints NAME without its last part: dirname /etc/ssh/sshd_config prints /etc/ssh. A name with no / gives . (the current directory).", see: ["basename(1)"], examples: [["dirname /var/log/syslog", "Prints /var/log."]] });

  // ---------------------------------------------------------------- archives
  page("tar", "tar", 1, "an archiving utility", {
    synopsis: ["tar -c [-zjJ] -f ARCHIVE FILE...", "tar -x [-zjJ] -f ARCHIVE [-C DIR] [MEMBER...]", "tar -t [-zjJ] -f ARCHIVE"],
    description: "tar packs many files and directories into one archive file and unpacks them again, keeping names, permissions and timestamps. By itself it doesn't compress; add -z, -j or -J to compress the archive with gzip, bzip2 or xz. The dash before the options is optional (tar czf works too). Leading / is removed from member names so that extraction can't overwrite system files.",
    options: [["-c, --create", "Create a new archive."], ["-x, --extract", "Extract files from an archive."], ["-t, --list", "List the archive's contents."], ["-r, --append", "Add files to the end of an archive (uncompressed archives only)."], ["-u, --update", "Add only files that are newer than the copies in the archive (uncompressed only)."], ["-f ARCHIVE", "The archive file name. Always needed in practice; put it last in a group: -czf name.tar.gz"], ["-v, --verbose", "List files as they are processed."], ["-z, --gzip", "Filter through gzip (.tar.gz, .tgz)."], ["-j, --bzip2", "Filter through bzip2 (.tar.bz2)."], ["-J, --xz", "Filter through xz (.tar.xz)."], ["-C DIR", "Change to DIR before extracting or creating."], ["-P, --absolute-names", "Keep the leading / in member names."], ["--wildcards", "Allow * and ? in member names when extracting or listing."]],
    examples: [["tar -czf site.tar.gz site/", "Create a gzip-compressed archive of site/."], ["tar -tzf site.tar.gz", "List it."], ["tar -xzf site.tar.gz -C /tmp", "Extract it into /tmp."]], see: ["gzip(1)", "bzip2(1)", "xz(1)", "zip(1)"] });
  page("gzip", "gzip", 1, "compress or expand files", { synopsis: ["gzip [OPTION]... FILE...", "gunzip FILE.gz...", "zcat FILE.gz..."], description: "gzip compresses each file and replaces it with FILE.gz, keeping the mode and timestamp. gunzip (or gzip -d) restores the original; zcat prints the uncompressed contents without changing the file. gzip compresses single files only; use tar to bundle several first.", options: [["-d, --decompress", "Decompress."], ["-k, --keep", "Keep the original file."], ["-c, --stdout", "Write to standard output and keep the file."], ["-r", "Compress every file in a directory tree, each on its own."], ["-1 ... -9", "Fast but larger (1) to slow but smallest (9). Default 6."]], see: ["bzip2(1)", "xz(1)", "tar(1)"], examples: [["gzip -k access.log", "Compress, but keep access.log too."], ["zcat access.log.gz | grep ERROR", "Search inside without decompressing to disk: zcat prints the text and the pipe hands it to grep (or head, less, wc ...)."], ["gzip -9 dump.sql", "Smallest output, slowest."]] });
  page("gunzip", "gunzip", 1, "expand gzip-compressed files", { synopsis: ["gunzip FILE.gz..."], description: "gunzip is the same as gzip -d.", see: ["gzip(1)"], examples: [["gunzip access.log.gz", "Restore access.log and remove the .gz."], ["gunzip -c access.log.gz > copy.log", "Write the text elsewhere and keep the .gz."]] });
  page("zcat", "zcat", 1, "print gzip-compressed files", { synopsis: ["zcat FILE.gz..."], description: "zcat is the same as gzip -dc: it prints the uncompressed data and leaves the file alone.", see: ["gzip(1)"], examples: [["zcat access.log.gz", "Print the uncompressed text; the .gz stays as it is."], ["zcat access.log.gz | less", "Page through it."], ["zcat access.log.gz | tail -n 5", "Only its last 5 lines."]] });
  page("bzip2", "bzip2", 1, "a block-sorting file compressor", { synopsis: ["bzip2 [OPTION]... FILE...", "bunzip2 FILE.bz2..."], description: "bzip2 compresses better than gzip but more slowly, and replaces each file with FILE.bz2. bunzip2 or bzip2 -d decompresses, and bzcat prints.", options: [["-d", "Decompress."], ["-k", "Keep the original file."], ["-1 ... -9", "Block size; 9 (default) compresses best."]], see: ["gzip(1)", "xz(1)"], examples: [["bzip2 bigfile", "Replace bigfile with bigfile.bz2."], ["bzip2 -k bigfile", "Keep the original too."], ["bzip2 -d bigfile.bz2", "Decompress, same as bunzip2."]] });
  page("bunzip2", "bunzip2", 1, "expand bzip2-compressed files", { synopsis: ["bunzip2 FILE.bz2..."], description: "bunzip2 is the same as bzip2 -d.", see: ["bzip2(1)"], examples: [["bunzip2 bigfile.bz2", "Restore bigfile."], ["bunzip2 -c bigfile.bz2 | head", "Look at the start without writing a file (bzcat does the same)."]] });
  page("xz", "xz", 1, "compress or decompress .xz files", { synopsis: ["xz [OPTION]... FILE...", "unxz FILE.xz..."], description: "xz usually compresses best of the three common tools and is used for kernel and package archives. It replaces each file with FILE.xz; unxz or xz -d reverses it, and xzcat prints.", options: [["-d", "Decompress."], ["-k", "Keep the original file."], ["-0 ... -9", "Compression preset; higher is smaller and slower. Default 6."]], see: ["gzip(1)", "bzip2(1)"], examples: [["xz bigfile", "Replace bigfile with bigfile.xz."], ["xz -k -6 bigfile", "Keep the original, default level."], ["xz -d bigfile.xz", "Decompress, same as unxz."]] });
  page("unxz", "unxz", 1, "decompress .xz files", { synopsis: ["unxz FILE.xz..."], description: "unxz is the same as xz -d.", see: ["xz(1)"], examples: [["unxz bigfile.xz", "Restore bigfile."], ["unxz -k bigfile.xz", "Restore it and keep the .xz."]] });
  page("zip", "zip", 1, "package and compress (archive) files", { synopsis: ["zip [OPTION]... ARCHIVE.zip FILE..."], description: "zip both bundles and compresses, in the format Windows and macOS open natively. Unlike gzip it keeps the original files. Directories need -r.", options: [["-r", "Include directories and everything in them."], ["-0 ... -9", "Store only (0) up to best compression (9)."], ["-q", "Quiet."]], see: ["unzip(1)", "tar(1)"], examples: [["zip notes.zip a.txt b.txt", "Bundle and compress two files."], ["zip -r site.zip website/", "A whole directory."]] });
  page("unzip", "unzip", 1, "list and extract files from a ZIP archive", { synopsis: ["unzip [OPTION]... ARCHIVE.zip"], description: "unzip extracts the files in a ZIP archive into the current directory.", options: [["-l", "List the contents without extracting."], ["-d DIR", "Extract into DIR."], ["-o", "Overwrite existing files without asking."], ["-q", "Quiet."]], see: ["zip(1)"], examples: [["unzip -l notes.zip", "List the contents."], ["unzip notes.zip -d extracted", "Extract into extracted/."]] });

  // ---------------------------------------------------------------- permissions and ownership
  page("chmod", "chmod", 1, "change file mode bits", {
    synopsis: ["chmod [-R] MODE[,MODE]... FILE...", "chmod [-R] OCTAL-MODE FILE..."],
    description: "chmod changes who may read (r), write (w) and execute (x) a file, separately for its user/owner (u), group (g) and others (o); a means all three. Symbolic modes add (+), remove (-) or set exactly (=) bits: u+x, go-w, a=r, u+rwx,g-x. Octal modes give each set as a digit, r=4 w=2 x=1: 755 is rwxr-xr-x, 640 is rw-r-----. A fourth leading digit sets the special bits: 4 SUID, 2 SGID, 1 sticky (4755, 2775, 1777); symbolic forms are u+s, g+s and +t. On a directory, r lists names, w creates and deletes entries, and x lets you enter it. Only the owner (or root) can chmod a file.",
    options: [["-R, --recursive", "Change files and directories recursively."], ["-v", "Report each change."]],
    examples: [["chmod u+x script.sh", "Let the owner run the script."], ["chmod 600 key.pem", "Owner read/write, nobody else anything."], ["chmod 1777 /shared", "World-writable, but only owners can delete their files."]], see: ["chown(1)", "chgrp(1)", "ls(1)", "umask"] });
  page("chown", "chown", 1, "change file owner and group", { synopsis: ["chown [-R] OWNER[:GROUP] FILE...", "chown [-R] :GROUP FILE..."], description: "chown changes the user and/or group that own each file. Only root can give a file to another user, so it is normally run with sudo. OWNER: also sets the group to the owner's login group.", options: [["-R, --recursive", "Operate on directories and their contents."]], examples: [["sudo chown -R www-data:www-data /var/www/site", "Hand a website to the web server account."]], see: ["chgrp(1)", "chmod(1)"] });
  page("chgrp", "chgrp", 1, "change group ownership", { synopsis: ["chgrp [-R] GROUP FILE..."], description: "chgrp changes the group of each file. A normal user may change the group of a file they own to any group they belong to.", options: [["-R", "Recursive."]], see: ["chown(1)"], examples: [["chgrp staff report.txt", "Give the file to group staff."], ["chgrp -R web /srv/site", "A whole tree."]] });
  page("umask", "umask", 1, "the default permission mask (bash builtin)", { synopsis: ["umask [MODE]"], description: "The umask removes permissions from newly created files. With the usual umask 022, new files are 644 (rw-r--r--) and new directories 755." });

  // ---------------------------------------------------------------- users, groups and identity
  page("id", "id", 1, "print real and effective user and group IDs", { synopsis: ["id [OPTION]... [USER]"], description: "id prints the user ID and name, the primary group, and every group the user belongs to.", options: [["-u", "Print only the user ID."], ["-g", "Print only the primary group ID."], ["-G", "Print all group IDs."], ["-n", "With -u, -g or -G, print names instead of numbers."]], see: ["groups(1)", "whoami(1)"], examples: [["id", "Your UID, primary group and every group."], ["id -u", "Just your numeric user ID."], ["id -Gn alice", "alice's groups by name."]] });
  page("groups", "groups", 1, "print the groups a user is in", { synopsis: ["groups [USER]..."], description: "groups lists the groups of each user (default: you). Group changes take effect at the next login.", see: ["id(1)"], examples: [["groups", "Your groups."], ["groups alice", "alice's groups."]] });
  page("whoami", "whoami", 1, "print effective user name", { synopsis: ["whoami"], description: "whoami prints the name of the user you are acting as right now, for example root inside sudo -i.", examples: [["sudo whoami", "Prints root: sudo runs the command as root."]] });
  page("who", "who", 1, "show who is logged on", { synopsis: ["who"], description: "who lists the users logged in now, with their terminal and login time. A tty is a local console; a pts is a pseudo-terminal such as an SSH session or a terminal window.", see: ["w(1)", "last(1)"], examples: [["who", "Everyone logged in now."], ["who | wc -l", "How many sessions."]] });
  page("w", "w", 1, "show who is logged on and what they are doing", { synopsis: ["w [OPTION]... [USER]"], description: "w starts with the same line as uptime (current time, uptime, number of users, load averages), then lists each login with its terminal, origin, login time, idle time and current command.", options: [["-h, --no-header", "Don't print the header."], ["-s, --short", "Short format: drop login time, JCPU and PCPU."], ["-i, --ip-addr", "Show IP addresses instead of host names in FROM."]], see: ["who(1)", "uptime(1)"], examples: [["w", "Logins plus what each one is running."], ["w -h", "Without the header lines."]] });
  page("last", "last", 1, "show a listing of last logged in users", { synopsis: ["last [USER] [reboot]", "lastb"], description: "last reads /var/log/wtmp and lists past logins, newest first, including whether the user is still logged in and reboots (last reboot). lastb shows failed login attempts from /var/log/btmp and needs root.", files: [["/var/log/wtmp", "Login records (binary; read with last)."], ["/var/log/btmp", "Failed login attempts (binary; read with lastb)."]], see: ["who(1)", "w(1)"], examples: [["last", "Recent logins, newest first."], ["last alice", "Only alice's logins."], ["last reboot", "When the system was restarted."], ["sudo lastb", "Failed login attempts (needs root)."]] });
  page("lastb", "lastb", 1, "show failed login attempts", { synopsis: ["lastb [USER]"], description: "lastb is last reading /var/log/btmp instead of wtmp, so it lists failed logins. The file is readable only by root, so run it with sudo.", examples: [["sudo lastb", "Every failed login attempt, newest first."], ["sudo lastb | head", "Only the most recent ones."]], see: ["last(1)"] });
  page("su", "su", 1, "run a command with a substitute user ID", { synopsis: ["su [-] [USER]", "su -c COMMAND [USER]"], description: "su starts a shell as another user (root by default) after asking for THAT user's password. su - (or su -l) starts a login shell: the environment and current directory are set up as if the user had logged in. On Ubuntu root has no password, so use sudo instead.", see: ["sudo(8)"], examples: [["su -", "A login shell as root, after root's password."], ["su - alice", "Become alice with her environment."], ["su -c 'whoami' alice", "Run one command as alice."]] });
  page("sudo", "sudo", 8, "execute a command as another user", { synopsis: ["sudo [-u USER] COMMAND", "sudo -i", "sudo -l"], description: "sudo runs one command as root (or another user) after asking for YOUR password, if the sudoers policy allows it. On Debian and Ubuntu members of the sudo group may run anything; on Fedora and RHEL it is the wheel group. Every use is logged. Redirections like > are done by your shell before sudo runs, so sudo echo x > /etc/file fails; use sudo tee instead.", options: [["-u USER", "Run as USER instead of root."], ["-i", "Start a root login shell."], ["-l", "List what you are allowed to run."]], files: [["/etc/sudoers", "The policy. Edit it only with visudo."]], see: ["su(1)", "visudo(8)"], examples: [["sudo apt update", "Run one command as root."], ["sudo -u alice ls ~alice", "Run a command as alice instead."], ["sudo -l", "What you are allowed to run."]] });
  page("passwd", "passwd", 1, "change user password", { synopsis: ["passwd [OPTION] [USER]"], description: "passwd changes your own password (it asks for the current one first) or, as root, anyone's. /usr/bin/passwd is SUID root, which is how a normal user can update /etc/shadow.", options: [["-l, --lock", "Lock the password by putting ! in front of the hash (root only)."], ["-u, --unlock", "Unlock it again."], ["-d, --delete", "Delete the password, leaving the account without one (root only)."], ["-e, --expire", "Expire the password so the user must choose a new one at next login."], ["-S, --status", "Show the status: name, P (usable password), L (locked) or NP (no password), date of last change, and aging values."]], see: ["passwd(5)", "shadow(5)", "chage(1)"], examples: [["passwd", "Change your own password."], ["sudo passwd alice", "Set alice's password as root."], ["sudo passwd -l alice", "Lock her password; -u unlocks it."], ["sudo passwd -S alice", "Short status: locked or set, last change."]] });
  page("passwd.5", "passwd", 5, "the password file", { synopsis: ["/etc/passwd"], description: "/etc/passwd lists every account, one per line, as seven colon-separated fields:\nname:password:UID:GID:GECOS:home:shell\nThe password field is x, meaning the hash is in /etc/shadow. UID 0 is root; system accounts usually have UIDs below 1000 and normal users 1000 and up. GID is the primary group. GECOS holds the full name and other comma-separated details. The file is readable by everyone.", examples: [["student:x:1000:1000:Lab Student,,,:/home/student:/bin/bash", "A normal user."]], see: ["shadow(5)", "group(5)", "passwd(1)"] });
  page("shadow", "shadow", 5, "shadowed password file", { synopsis: ["/etc/shadow"], description: "/etc/shadow holds the password hashes and aging information, readable only by root (and the shadow group). Nine colon-separated fields:\nname:hash:lastchange:min:max:warn:inactive:expire:reserved\nA hash starting with ! is locked; * or ! alone means no password login. Dates are days since 1 January 1970; a last-change of 0 forces a new password at next login.", see: ["passwd(5)", "chage(1)"], examples: [["sudo grep alice /etc/shadow", "alice's hash and aging fields (root only)."]] });
  page("group", "group", 5, "user group file", { synopsis: ["/etc/group"], description: "/etc/group lists groups as four colon-separated fields:\nname:password:GID:members\nmembers is a comma-separated list of users who have this as a supplementary group. A user's primary group is set in /etc/passwd and is usually not repeated here.", see: ["gshadow(5)", "passwd(5)", "groupadd(8)"], examples: [["grep staff /etc/group", "The staff group and its members."], ["cut -d: -f1 /etc/group", "Only the group names."]] });
  page("gshadow", "gshadow", 5, "shadowed group file", { synopsis: ["/etc/gshadow"], description: "/etc/gshadow holds group passwords (rarely used) and group administrators, readable only by root:\nname:password:administrators:members", see: ["group(5)"], examples: [["sudo cat /etc/gshadow", "Needs root."]] });
  page("useradd", "useradd", 8, "create a new user", {
    synopsis: ["useradd [OPTION]... LOGIN", "useradd -D"],
    description: "useradd adds an account to /etc/passwd, /etc/shadow and /etc/group. By default it creates a matching private group but no home directory on Debian and Ubuntu (Fedora creates one), and the password is locked until passwd sets it. Defaults come from /etc/default/useradd and /etc/login.defs; useradd -D shows them. Needs root. (adduser is a friendlier interactive script on Debian.)",
    options: [["-m", "Create the home directory and copy /etc/skel into it."], ["-M", "Don't create a home directory."], ["-d HOME", "Use HOME as the home directory."], ["-s SHELL", "Login shell, for example /bin/bash."], ["-u UID", "Use this user ID."], ["-g GROUP", "Primary group (instead of a new private group)."], ["-G G1,G2", "Supplementary groups."], ["-c COMMENT", "The GECOS field, usually the full name."], ["-e YYYY-MM-DD", "Date the account expires."], ["-f DAYS", "Days after the password expires before the account is disabled."]],
    examples: [["sudo useradd -m -s /bin/bash -G sudo ada", "A user who can use sudo."]], files: [["/etc/skel", "Files copied into new home directories."]], see: ["usermod(8)", "userdel(8)", "passwd(1)", "groupadd(8)"] });
  page("usermod", "usermod", 8, "modify a user account", { synopsis: ["usermod [OPTION]... LOGIN"], description: "usermod changes an existing account. Careful: -G alone REPLACES the user's supplementary groups; add -a to append instead.", options: [["-aG GROUP", "Add the user to GROUP, keeping the other groups."], ["-G G1,G2", "Set the supplementary groups to exactly this list."], ["-g GROUP", "Change the primary group."], ["-s SHELL", "Change the login shell."], ["-c COMMENT", "Change the GECOS field."], ["-d HOME", "Change the home directory."], ["-L / -U", "Lock / unlock the password."], ["-l NEWNAME", "Rename the account."]], see: ["useradd(8)", "gpasswd(1)"], examples: [["sudo usermod -aG docker alice", "Add alice to docker, keeping her other groups."], ["sudo usermod -s /bin/zsh alice", "Change her login shell."], ["sudo usermod -L alice", "Lock the account."]] });
  page("userdel", "userdel", 8, "delete a user account and related files", { synopsis: ["userdel [-r] LOGIN"], description: "userdel removes the account from the account files. Its home directory and files stay unless -r is given. Files elsewhere keep the old UID and show up as a number in ls -l.", options: [["-r, --remove", "Also remove the home directory and mail spool."], ["-f", "Force, even if the user is logged in."]], see: ["useradd(8)"], examples: [["sudo userdel bob", "Remove the account, keep /home/bob."], ["sudo userdel -r bob", "Remove the account and its home directory."]] });
  page("groupadd", "groupadd", 8, "create a new group", { synopsis: ["groupadd [-g GID] GROUP"], description: "groupadd adds a group to /etc/group and /etc/gshadow. Needs root.", options: [["-g GID", "Use this group ID."], ["-r", "Create a system group (GID below 1000)."]], see: ["groupdel(8)", "usermod(8)", "group(5)"], examples: [["sudo groupadd developers", "Create a group."], ["sudo groupadd -g 1500 qa", "With a chosen GID."]] });
  page("groupdel", "groupdel", 8, "delete a group", { synopsis: ["groupdel GROUP"], description: "groupdel removes a group. It refuses to remove a group that is still some user's primary group.", see: ["groupadd(8)"], examples: [["sudo groupdel developers", "Remove a group."]] });
  page("groupmems", "groupmems", 8, "administer members of a user's primary group", { synopsis: ["groupmems -g GROUP [-l | -a USER | -d USER | -p]"], description: "groupmems lists and changes the members of a group.", options: [["-g GROUP", "The group to work on (root only)."], ["-l, --list", "List the members."], ["-a USER", "Add USER."], ["-d USER", "Remove USER."], ["-p, --purge", "Remove every member."]], see: ["group(5)", "usermod(8)"], examples: [["sudo groupmems -g developers -l", "List members."], ["sudo groupmems -g developers -a alice", "Add alice."]] });
  page("chage", "chage", 1, "change user password expiry information", { synopsis: ["chage [OPTION]... LOGIN"], description: "chage shows or changes the password aging fields of /etc/shadow.", options: [["-l", "List the aging information (allowed for your own account)."], ["-E YYYY-MM-DD", "Account expiry date (-1 removes it)."], ["-M DAYS", "Maximum days a password stays valid."], ["-m DAYS", "Minimum days between changes."], ["-W DAYS", "Warning days before expiry."], ["-I DAYS", "Inactive days after expiry before the account locks."], ["-d 0", "Force a password change at next login."]], see: ["shadow(5)", "passwd(1)"], examples: [["chage -l alice", "alice's password aging."], ["sudo chage -M 90 alice", "Require a new password every 90 days."], ["sudo chage -d 0 alice", "Force a change at next login."]] });
  page("chsh", "chsh", 1, "change login shell", { synopsis: ["chsh [-s SHELL] [USER]"], description: "chsh changes a login shell in /etc/passwd. Normal users can change only their own, to one of the shells listed in /etc/shells, and are asked for their password.", options: [["-s SHELL", "The new shell, as a full path."], ["-l", "List the allowed shells."]], files: [["/etc/shells", "Valid login shells."]], see: ["chfn(1)", "passwd(5)"], examples: [["chsh -s /bin/bash", "Change your own login shell."], ["cat /etc/shells", "The shells you may choose."]] });
  page("chfn", "chfn", 1, "change real user name and information", { synopsis: ["chfn [-f NAME] [-r ROOM] [-w PHONE] [-h PHONE] [USER]"], description: "chfn changes the GECOS (comment) field of /etc/passwd: full name, room number, work phone and home phone, separated by commas.", options: [["-f NAME", "Full name."], ["-r ROOM", "Room number."], ["-w PHONE", "Work phone."], ["-h PHONE", "Home phone."]], see: ["chsh(1)", "finger(1)"], examples: [["chfn -f 'Alice Smith'", "Set your full name."], ["sudo chfn -r 101 alice", "Set alice's room number."]] });

  // ---------------------------------------------------------------- processes and system information
  page("ps", "ps", 1, "report a snapshot of the current processes", {
    synopsis: ["ps [OPTIONS]"],
    description: "ps lists processes once (top keeps refreshing). With no options it shows only your processes on this terminal. ps accepts UNIX options with a dash (ps -ef) and BSD options without one (ps aux); both are common.",
    options: [["-e, -A", "Every process."], ["-f", "Full format: UID, PID, parent PID (PPID), start time, terminal and full command line."], ["-u USER", "Processes of USER."], ["-p PID", "The given process IDs."], ["--forest, -H", "Show children indented under their parents."], ["aux", "BSD style: every process (a, x) with user-oriented columns (u): USER, PID, %CPU, %MEM, VSZ, RSS, TTY, STAT, START, TIME, COMMAND."], ["auxf", "The same as a tree."]],
    sections: [["PROCESS STATE CODES (STAT)", ["R running    S sleeping    D waiting for I/O    T stopped    Z zombie", "s session leader    + in the foreground    < high priority    l multi-threaded"]]], see: ["top(1)", "kill(1)", "pstree(1)", "proc(5)"], examples: [["ps", "Your processes in this terminal."], ["ps -ef | grep sshd", "Find a process by name in the full list."], ["ps aux --sort=-%mem | head -n 5", "The biggest memory users."], ["ps -f --forest", "Children indented under their parents."]] });
  page("top", "top", 1, "display Linux processes", { synopsis: ["top [-b] [-n N]"], description: "top shows a live, refreshing view: a summary (uptime and load average, task counts, CPU use, memory and swap) followed by the busiest processes. Interactive keys: q quit, k kill a PID, M sort by memory, P sort by CPU, h help.", options: [["-b", "Batch mode: plain output that can be redirected."], ["-n N", "Exit after N refreshes."]], see: ["ps(1)", "uptime(1)", "free(1)"], examples: [["top", "Live view; q quits, P sorts by CPU, M by memory."], ["top -b -n 1 | head -n 15", "One snapshot, printed like a normal command."]] });
  page("kill", "kill", 1, "send a signal to a process", { synopsis: ["kill [-SIGNAL] PID...", "kill -l"], description: "kill sends a signal to processes, by default SIGTERM (15), which asks the program to clean up and exit. SIGKILL (9) can't be caught or ignored and stops the process immediately, without cleanup, so use it only when TERM doesn't work. You can signal your own processes; root can signal any. Bash has a builtin kill.", options: [["-l", "List the signal names."], ["-9, -KILL", "Send SIGKILL."], ["-15, -TERM", "Send SIGTERM (default)."], ["-HUP", "Hang up; many daemons reload their configuration."]], see: ["ps(1)", "top(1)", "killall(1)"], examples: [["kill 2412", "Ask process 2412 to exit (SIGTERM)."], ["kill -9 2412", "Force it (SIGKILL)."], ["kill -l", "List the signal names and numbers."]] });
  page("free", "free", 1, "display amount of free and used memory in the system", { synopsis: ["free [OPTION]"], description: "free shows total, used and free RAM and swap. buff/cache is memory the kernel uses for caching files and gives back when programs need it, so 'available' is the best estimate of memory you can still use. The numbers come from /proc/meminfo.", options: [["-b, -k, -m, -g", "Show bytes, KiB (default), MiB or GiB."], ["-h", "Human-readable units."], ["-t", "Add a total line."]], see: ["top(1)", "proc(5)"], examples: [["free -h", "Memory and swap in human-readable units."], ["free -m", "In mebibytes."]] });
  page("uptime", "uptime", 1, "tell how long the system has been running", { synopsis: ["uptime"], description: "uptime prints the current time, how long the system has been up, the number of logged-in users, and the load averages over the last 1, 5 and 15 minutes. A load equal to the number of CPU cores means they are fully busy.", examples: [["uptime", "Time up, users and load averages."]] });
  page("uname", "uname", 1, "print system information", { synopsis: ["uname [-a] [-s] [-r] [-m] [-n]"], description: "uname prints information about the running kernel.", options: [["-a", "Everything."], ["-r", "Kernel release, for example 6.8.0-45-generic."], ["-m", "Machine hardware name, for example x86_64."], ["-n", "Host name."], ["-s", "Kernel name (Linux)."]], examples: [["uname -r", "Kernel version."], ["uname -a", "Everything at once."]] });
  page("hostname", "hostname", 1, "show or set the system's host name", { synopsis: ["hostname"], description: "hostname prints the machine's name. It is stored in /etc/hostname; hostnamectl changes it permanently on systemd systems.", examples: [["hostname", "This machine's name."], ["cat /etc/hostname", "Where the name is stored."]] });
  page("lsblk", "lsblk", 8, "list block devices", { synopsis: ["lsblk [-f]"], options: [["-f, --fs", "Show file system type, label and UUID for each partition."]], description: "lsblk shows disks and partitions as a tree with their sizes and mount points. SD and eMMC cards appear as /dev/mmcblk0 with partitions mmcblk0p1, mmcblk0p2. SATA, SAS and USB disks are named /dev/sda, /dev/sdb and so on with partitions sda1, sda2; NVMe disks are /dev/nvme0n1 with partitions nvme0n1p1; very old IDE disks were /dev/hda.", see: ["df(1)", "fdisk(8)"], examples: [["lsblk", "Disks and partitions as a tree."], ["lsblk -f", "Plus file system type and UUID."]] });
  page("df", "df", 1, "report file system disk space usage", { synopsis: ["df [-h]"], description: "df shows each mounted file system with its size, used and available space and mount point.", options: [["-h", "Human-readable sizes."]], see: ["du(1)", "lsblk(8)"], examples: [["df -h", "Every mounted file system, human-readable."], ["df -h /home", "Only the one holding /home."]] });
  page("dmesg", "dmesg", 1, "print or control the kernel ring buffer", { synopsis: ["dmesg [-T]"], description: "dmesg prints the kernel's message buffer: hardware detected at boot, drivers loading, and events such as a USB disk being plugged in. On most current systems it needs root. journalctl -k shows the same messages from the journal.", options: [["-T", "Show human-readable timestamps instead of seconds since boot."]], see: ["journalctl(1)"], examples: [["dmesg | tail", "The newest kernel messages."], ["dmesg | grep -i usb", "Messages about USB devices."]] });
  page("journalctl", "journalctl", 1, "print log entries from the systemd journal", {
    synopsis: ["journalctl [OPTION]..."],
    description: "journalctl reads the systemd journal, a binary log of messages from the kernel, services and programs. Members of the adm and systemd-journal groups (and root) see every message. Without options it prints everything, oldest first.",
    options: [["-u UNIT", "Only messages from a unit, for example -u ssh or -u cron.service."], ["-k, --dmesg", "Only kernel messages from this boot (like dmesg)."], ["-b [N]", "Only this boot, or boot N (-1 is the previous one)."], ["--list-boots", "List the recorded boots."], ["-f, --follow", "Keep printing new messages, like tail -f."], ["-n N", "Only the last N lines."], ["-r", "Newest first."], ["-p PRIORITY", "Only messages at or above a priority such as err."]], see: ["systemctl(1)", "dmesg(1)"], examples: [["journalctl -u ssh", "Messages from the ssh service."], ["journalctl -n 20", "The last 20 entries."], ["journalctl -b -p err", "Errors since this boot."]] });
  page("systemctl", "systemctl", 1, "control the systemd system and service manager", { synopsis: ["systemctl [COMMAND] [UNIT]"], description: "systemctl starts, stops and inspects services (units). status shows whether a service runs, its main PID and its newest log lines. Changing a service needs root.", options: [["status UNIT", "Show state and recent log messages."], ["start / stop / restart UNIT", "Change whether it runs now."], ["enable / disable UNIT", "Change whether it starts at boot."], ["is-active UNIT", "Print active or inactive."], ["list-units", "List loaded units."]], see: ["journalctl(1)"], examples: [["systemctl status ssh", "Is ssh running, its PID and recent log lines."], ["sudo systemctl restart ssh", "Restart a service."], ["systemctl is-active cron", "Prints active or inactive."]] });
  page("proc", "proc", 5, "process information pseudo-filesystem", { synopsis: ["/proc"], description: "/proc is generated by the kernel in memory. Each running process has a directory named after its PID: /proc/PID/cmdline holds its command line (arguments separated by NUL bytes), status its state and memory. System-wide files include /proc/meminfo (used by free), /proc/cpuinfo, /proc/version and /proc/partitions. /proc/self points to the process reading it.", examples: [["cat /proc/cpuinfo", "CPU details."], ["cat /proc/meminfo | head -n 3", "Total and free memory."], ["cat /proc/$$/cmdline", "The command line of this shell."]] });
  page("hier", "hier", 7, "description of the file system hierarchy", { synopsis: ["/"], description: "/bin and /usr/bin programs for everyone; /sbin and /usr/sbin administration programs; /boot the kernel (vmlinuz-VERSION) and initial RAM disk; /dev device files; /etc system configuration; /home users' home directories; /root root's home; /proc and /sys kernel interfaces; /run runtime data, cleared at boot; /tmp temporary files, often cleared at boot; /var/tmp temporary files kept across reboots; /var/log log files; /usr/share/doc package documentation; /opt add-on software. On current Debian, Ubuntu and Fedora /bin and /sbin are links to /usr/bin and /usr/sbin.", examples: [["ls /", "The top-level directories described above."]] });

  // ---------------------------------------------------------------- networking
  page("ip", "ip", 8, "show / manipulate routing, network devices, interfaces", {
    synopsis: ["ip [-4|-6] [-br] OBJECT COMMAND", "OBJECT := link | address | route"],
    description: "ip (from iproute2) replaces the older ifconfig and route commands. Objects and commands can be abbreviated: ip a is ip address show, ip r is ip route show. Changes need root and last until reboot; permanent settings go in NetworkManager or netplan configuration.",
    options: [["ip link show", "List network interfaces and whether they are UP."], ["ip link set DEV up|down", "Enable or disable an interface."], ["ip address show [dev DEV]", "Show IPv4 and IPv6 addresses."], ["ip address add ADDR/PREFIX dev DEV", "Add an address, for example 192.168.10.10/24."], ["ip address del ADDR/PREFIX dev DEV", "Remove an address."], ["ip route show", "Show the routing table; 'default via' is the gateway."], ["ip route add default via GATEWAY", "Set the default gateway."], ["ip -6 route add default via GATEWAY", "Set the IPv6 default gateway."], ["-br", "Brief one-line-per-interface output."]],
    see: ["ss(8)", "ping(8)"], examples: [["ip a", "Short for ip address show."], ["ip -br link", "One line per interface."], ["ip r", "The routing table; the default route is the gateway."]] });
  page("ping", "ping", 8, "send ICMP ECHO_REQUEST to network hosts", { synopsis: ["ping [-c COUNT] HOST", "ping6 HOST", "ping -6 HOST"], description: "ping sends echo requests and reports each reply with its round-trip time, then a summary of packet loss. On Linux it keeps going until Ctrl+C unless -c is given. Some hosts and firewalls block ICMP, so no reply doesn't always mean the host is down.", options: [["-c COUNT", "Stop after COUNT replies."], ["-4 / -6", "Use IPv4 or IPv6 only (ping6 is the same as ping -6)."], ["-q", "Print only the summary."]], see: ["ip(8)", "host(1)"], examples: [["ping -c 3 example.com", "Three echo requests, then a summary."], ["ping -c 2 -6 example.com", "Over IPv6."]] });
  page("ping6", "ping6", 8, "send ICMPv6 echo requests", { synopsis: ["ping6 [-c COUNT] HOST"], description: "ping6 is the same as ping -6 and takes the same options.", options: [["-c COUNT", "Stop after COUNT replies."]], see: ["ping(8)"], examples: [["ping6 -c 3 ::1", "Three echo requests to the IPv6 loopback address."]] });
  page("host", "host", 1, "DNS lookup utility", { synopsis: ["host [-t TYPE] NAME", "host ADDRESS"], description: "host asks DNS for the addresses and mail servers of a name, or with an IP address it does a reverse (PTR) lookup. It doesn't read /etc/hosts.", options: [["-t TYPE", "Ask for one record type: A, AAAA, MX, TXT, CNAME, NS, PTR."]], see: ["dig(1)", "resolv.conf(5)"], examples: [["host example.com", "Its addresses and mail servers."], ["host -t MX example.com", "Only the mail servers."], ["host 8.8.8.8", "Reverse lookup."]] });
  page("dig", "dig", 1, "DNS lookup utility", { synopsis: ["dig [@SERVER] NAME [TYPE] [+short]", "dig -x ADDRESS"], description: "dig shows the full DNS answer: the question, the answer records with their TTL, which server answered and how long it took. It is the standard tool for troubleshooting DNS. Record types: A (IPv4), AAAA (IPv6), MX (mail server), CNAME (alias), TXT (text), NS (name servers), PTR (reverse).", options: [["+short", "Print only the answers."], ["-x ADDRESS", "Reverse lookup."], ["@SERVER", "Ask this DNS server instead of the ones in /etc/resolv.conf."]], see: ["host(1)", "resolv.conf(5)"], examples: [["dig example.com", "The full answer with TTLs."], ["dig +short example.com", "Just the addresses."], ["dig example.com MX", "Mail servers."], ["dig -x 8.8.8.8", "Reverse lookup."]] });
  page("ss", "ss", 8, "another utility to investigate sockets", { synopsis: ["ss [OPTIONS]"], description: "ss lists network connections and listening ports; it replaces netstat. By default it shows established connections only.", options: [["-t", "TCP sockets."], ["-u", "UDP sockets."], ["-l", "Listening sockets only."], ["-a", "Listening and established."], ["-p", "Show the process using each socket (root sees all)."], ["-n", "Show numbers instead of service names."], ["-4 / -6", "IPv4 or IPv6 only."], ["-s", "Summary counts per protocol."]], examples: [["sudo ss -tulpn", "Every listening TCP and UDP port with its program."]], see: ["ip(8)", "netstat(8)"] });
  page("netstat", "netstat", 8, "print network connections (deprecated)", { synopsis: ["netstat [-tulpn]"], description: "netstat is the older tool replaced by ss; it is still found on many systems.", see: ["ss(8)"], examples: [["netstat -tlnp", "Listening TCP ports, like ss -tlnp."]] });
  page("hosts", "hosts", 5, "static table lookup for hostnames", { synopsis: ["/etc/hosts"], description: "/etc/hosts maps names to IP addresses locally, one address per line followed by one or more names. It is normally checked before DNS (see /etc/nsswitch.conf), so it works without a DNS server and can override DNS.", examples: [["192.168.1.15  nas.lan nas", "nas and nas.lan resolve to 192.168.1.15."]], see: ["resolv.conf(5)", "host(1)"] });
  page("resolv.conf", "resolv.conf", 5, "resolver configuration file", { synopsis: ["/etc/resolv.conf"], description: "/etc/resolv.conf lists the DNS servers to ask (nameserver lines) and search domains. On systemd systems it often points to the local stub resolver 127.0.0.53 and is managed automatically.", see: ["hosts(5)", "dig(1)"], examples: [["cat /etc/resolv.conf", "The DNS servers this machine asks."]] });
  page("fstab", "fstab", 5, "static information about the filesystems", { synopsis: ["/etc/fstab"], description: "Each line describes a file system to mount at boot: device, mount point, type, options, dump and fsck order.", examples: [["cat /etc/fstab", "What is mounted at boot."]] });
  page("nano", "nano", 1, "a small and friendly text editor", { synopsis: ["nano FILE"], description: "nano shows its commands at the bottom of the screen; ^ means Ctrl. Ctrl+O saves, Ctrl+X exits, Ctrl+W searches, Ctrl+K cuts a line and Ctrl+U pastes it.", see: ["vi(1)"], examples: [["nano notes.txt", "Edit a file; Ctrl+O saves, Ctrl+X exits."], ["sudo nano /etc/hosts", "Edit a system file as root."]] });
  page("vi", "vi", 1, "a modal text editor", { synopsis: ["vi FILE"], description: "vi starts in normal mode, where keys are commands. Press i to insert text and Esc to go back. In normal mode, :w saves, :q quits, :wq saves and quits, :q! quits without saving, dd deletes a line and /text searches. vim is the improved version found on most systems.", see: ["nano(1)"], examples: [["vi notes.txt", "i to type, Esc, then :wq to save and quit."]] });
  page("vim", "vim", 1, "Vi IMproved, a programmer's text editor", { synopsis: ["vim FILE"], description: "vim is the improved vi: same modes and commands, plus syntax highlighting and undo history. Esc then :wq saves and quits.", see: ["vi(1)"], examples: [["vim notes.txt", "Esc then :q! leaves without saving."]] });

  // ---------------------------------------------------------------- software packages
  page("apt", "apt", 8, "command-line interface for the Debian/Ubuntu package manager", {
    synopsis: ["apt [OPTIONS] COMMAND [PACKAGE]..."],
    description: "apt installs, removes and searches software packages from the distribution's repositories on Debian, Ubuntu and related systems, resolving dependencies automatically. It is the friendly front end; apt-get and apt-cache are the older tools with the same engine, preferred in scripts because their output doesn't change. Changing the system needs root.",
    options: [["update", "Download the current package lists from the repositories."], ["search WORD...", "Search package names and descriptions."], ["show PACKAGE", "Show details about a package."], ["install PACKAGE...", "Install packages and their dependencies."], ["remove PACKAGE...", "Remove packages but keep their configuration files."], ["purge PACKAGE...", "Remove packages and their configuration files."], ["list --installed", "List installed packages."], ["-y", "Answer yes to questions."]],
    see: ["apt-get(8)", "apt-cache(8)", "dpkg(1)"], examples: [["sudo apt update", "Refresh the package lists first."], ["apt search 'text editor'", "Find packages."], ["sudo apt install -y tree", "Install without the yes/no question."], ["apt list --installed | grep tree", "Is it installed?"]] });
  page("apt-get", "apt-get", 8, "APT package handling utility", { synopsis: ["apt-get [-y] install|remove|purge|update PACKAGE..."], description: "apt-get is the classic command-line tool for installing (install), removing (remove, purge) and updating the package lists (update). Its output is stable, so it's preferred in scripts. Searching is done with apt-cache.", see: ["apt(8)", "apt-cache(8)"], examples: [["sudo apt-get install tree", "Install a package."], ["sudo apt-get purge tree", "Remove it with its configuration files."]] });
  page("apt-cache", "apt-cache", 8, "query the APT package cache", { synopsis: ["apt-cache search WORD...", "apt-cache show PACKAGE"], description: "apt-cache searches and shows information about packages without changing anything, so it doesn't need root.", see: ["apt(8)", "apt-get(8)"], examples: [["apt-cache search editor", "Search names and descriptions."], ["apt-cache show tree", "Version, size, dependencies."]] });
  page("dpkg", "dpkg", 1, "package manager for Debian", { synopsis: ["dpkg -l [PATTERN]", "dpkg -L PACKAGE", "dpkg -s PACKAGE", "dpkg -i FILE.deb"], description: "dpkg is the low-level tool that installs, removes and lists individual .deb packages. It doesn't download anything or resolve dependencies; apt does that and calls dpkg.", options: [["-l [PATTERN]", "List packages; ii means installed, rc means removed but configuration files remain."], ["-L PACKAGE", "List the files a package installed."], ["-s PACKAGE", "Show a package's status."], ["-i FILE.deb", "Install a downloaded package file."], ["-r / -P PACKAGE", "Remove / purge a package."]], see: ["apt(8)"], examples: [["dpkg -l | grep bash", "Is bash installed, and which version."], ["dpkg -L tree", "Every file the package installed."], ["sudo dpkg -i tool.deb", "Install a downloaded .deb."]] });
  page("dnf", "dnf", 8, "package manager for Fedora and Red Hat Enterprise Linux", { synopsis: ["dnf [-y] COMMAND [PACKAGE]..."], description: "dnf installs, removes and searches RPM packages from the repositories on Fedora, RHEL, CentOS Stream, AlmaLinux and Rocky Linux, resolving dependencies. It asks for confirmation unless -y is given. It replaced yum; on current systems yum is a link to dnf.", options: [["search WORD...", "Search names and summaries."], ["info PACKAGE", "Show details."], ["install PACKAGE...", "Install packages."], ["remove PACKAGE...", "Remove packages."], ["list --installed", "List installed packages."], ["-y", "Assume yes."]], see: ["yum(8)", "rpm(8)"], examples: [["dnf search editor", "Search packages."], ["sudo dnf install -y tree", "Install one."], ["dnf list --installed | grep tree", "Is it installed?"]] });
  page("yum", "yum", 8, "the older Red Hat package manager (now dnf)", { synopsis: ["yum [-y] install|remove|search PACKAGE..."], description: "yum was the package manager of Red Hat systems before dnf. Commands are the same; on current systems yum runs dnf.", see: ["dnf(8)", "rpm(8)"], examples: [["sudo yum install tree", "Install on older Red Hat systems."]] });
  page("rpm", "rpm", 8, "RPM package manager", { synopsis: ["rpm -qa", "rpm -qi PACKAGE", "rpm -ql PACKAGE", "rpm -i FILE.rpm"], description: "rpm is the low-level tool for .rpm packages, the counterpart of dpkg on Red Hat systems. Queries start with -q.", options: [["-qa", "List all installed packages."], ["-qi PACKAGE", "Information about an installed package."], ["-ql PACKAGE", "Files it installed."], ["-i / -U FILE.rpm", "Install / upgrade a package file."], ["-e PACKAGE", "Erase (remove) a package."]], see: ["dnf(8)"], examples: [["rpm -qa | grep bash", "Is bash installed."], ["rpm -qi bash", "Details about it."], ["rpm -ql bash | head", "The first files it installed."]] });
  page("figlet", "figlet", 1, "display large characters made up of ordinary screen characters", { synopsis: ["figlet [TEXT]"], description: "figlet prints its text as a large banner. (The lab version uses a simple built-in font.)", examples: [["figlet Hello", "Print Hello in big letters."]] });
  page("cowsay", "cowsay", 1, "configurable speaking cow", { synopsis: ["cowsay [TEXT]"], description: "cowsay prints a cow with a speech balloon holding your text. A classic demo package.", examples: [["cowsay moo", "A cow says moo."]] });
  page("lscpu", "lscpu", 1, "display information about the CPU architecture", { synopsis: ["lscpu"], description: "lscpu summarises the processor: architecture (x86_64, aarch64...), number of CPUs and cores, model name, speed, caches and flags such as vmx/svm (hardware virtualization). It reads /proc/cpuinfo and /sys.", see: ["proc(5)", "lsblk(8)"], examples: [["lscpu", "CPU architecture, model and core count."], ["lscpu | grep Model", "Just the model name."]] });
  page("os-release", "os-release", 5, "operating system identification", { synopsis: ["/etc/os-release"], description: "/etc/os-release names the distribution and its version as shell-style variables: NAME, VERSION_ID, ID, ID_LIKE, PRETTY_NAME.", examples: [["cat /etc/os-release", "Which distribution and version this is."], ["grep PRETTY_NAME /etc/os-release", "The one-line name."]] });

  return P;
});
